Here is the root cause:
The kernel panics on PV domains because the function `native_smp_cpus_done()` was only called for HVM domains, leading to the absence of the necessary calculation for `__max_logical_packages` in PV domains. This oversight resulted in an incorrect estimation of logical packages, causing instability and crashes in the system.

Here is the patch:

 void __init xen_smp_cpus_done(unsigned int max_cpus)
 {
 	int cpu, rc, count = 0;

 	if (xen_hvm_domain())
 		native_smp_cpus_done(max_cpus);
+	else
+		calculate_max_logical_packages();

 	if (xen_have_vcpu_info_placement)
 		return;

 	for_each_online_cpu(cpu) {
 		if (xen_vcpu_nr(cpu) < MAX_VIRT_CPUS)
 			continue;

 		rc = cpu_down(cpu);

 		if (rc == 0) {
 			/*
 			 * Reset vcpu_info so this cpu cannot be onlined again.
 			 */
 			xen_vcpu_info_reset(cpu);
 			count++;
 		} else {
 			pr_warn("%s: failed to bring CPU %d down, error %d\n",
 				__func__, cpu, rc);
 		}
 	}
 	WARN(count, "%s: brought %d CPUs offline\n", __func__, count);
 }



